`,Mt(t.p,{children:"The adoption of Vision-Language Models (VLMs) in embodied AI agents, while being effective, brings safety concerns such as jailbreaking. Prior work have explored the possibility of directly jailbreaking the embodied agents through elaborated multi-modal prompts. However, no prior work has studied or even reported indirect jailbreaks in embodied AI, where a black-box attacker induces a jailbreak without issuing direct prompts to the embodied agent."}),`
`,Mt(t.p,{children:"In this paper, we propose, for the first time, indirect environmental jailbreak (IEJ), a novel attack to jailbreak embodied AI via indirect prompt injected into the environment, such as malicious instructions written on a wall. Our key insight is that embodied AI does not ''think twice'' about the instructions provided by the environment---a blind trust that attackers can exploit to jailbreak the embodied agent."}),`
`,Mt(t.p,{children:"We further design and implement open-source prototypes of two fully-automated frameworks: SHAWSHANK, the first automatic attack generation framework for the proposed attack IEJ; and SHAWSHANK-FORGE, the first automatic benchmark generation framework for IEJ. Then, using SHAWSHANK-FORGE, we automatically construct SHAWSHANK-BENCH, the first benchmark for indirectly jailbreaking embodied agents. Together, our two frameworks and one benchmark answer the questions of what content can be used for malicious IEJ instructions, where they should be placed, and how IEJ can be systematically evaluated."}),`
`,Mt(t.p,{children:"Evaluation results show that SHAWSHANK outperforms eleven existing methods across 3,957 task-scene combinations and compromises all six tested VLMs. Furthermore, current defenses only partially mitigate our attack, and we have responsibly disclosed our findings to all affected VLM vendors."})]})}function OY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt(Cb,{...e})}):Cb(e)}const IY={__name:"Abstract",setup(e){return(t,n)=>{const o=We("el-divider"),a=We("el-col"),l=We("el-row");return E(),D("div",null,[V(o),V(l,{justify:"center"},{default:Y(()=>[V(a,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[V(s(OY))]),_:1})]),_:1})])}}};function _b(e){const t={h1:"h1",img:"img",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Comparison between traditional jailbreak methods and Indirect Environmental Jailbreaking (IEJ)"}),`
