`,Mt(t.p,{children:"Our method demonstrates two outcomes: (a) Jailbreaking and (b) Denial-of-Service (DoS) attacks, both leveraging visual environmental manipulation."})]})}function NY(e={}){const{wrapper:t}=e.components||{};return t?Mt(t,{...e,children:Mt(_b,{...e})}):_b(e)}const xY={__name:"Markdown",setup(e){return(t,n)=>{const o=We("el-divider"),a=We("el-col"),l=We("el-row");return E(),D("div",null,[V(o),V(l,{justify:"center"},{default:Y(()=>[V(a,{xs:24,sm:20,md:16,lg:12,xl:12},{default:Y(()=>[V(s(NY))]),_:1})]),_:1})])}}};function Sb(e){const t={h1:"h1",img:"img",p:"p",...e.components};return Mt(Be,{children:[Mt(t.h1,{children:"Shawshank framework"}),`
